"""Read-only Gateway 406 source/configuration samples against a fixed Git commit."""
import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import threading
import time
import zlib
import base64

REF = '443cbd8ab6e2e74298075976fa68af079c1f7100'
EXPECTED = {
    'gateway': (406, 70, 'deerflow.local/deer-flow-gateway@sha256:f8faded6240cbc6d98c7dbfe30388a7ff4c3f4df243f0d6409b1f6a026c19b38'),
    'frontend': (239, 2, 'deerflow.local/deer-flow-frontend@sha256:97a84226f1c9f77871c05cebaae1fa42b7525644edc844bccf75e29518ba44c1'),
}
ENV = {'OA_POLICY_FLOW_RUN_TIMEOUT_SECONDS': '3600', 'DEERFLOW_BROWSER_NAVIGATE_ENABLED': 'false', 'DEERFLOW_LLM_PERFORMANCE_LOGS': 'true', 'DEERFLOW_LLM_PERFORMANCE_BATCH': '20261103-evening', 'OA_POLICY_FLOW_ENABLED': 'true', 'OA_POLICY_FLOW_MULTI_RESULT_ENABLED': 'true', 'OA_POLICY_FLOW_CALLBACK_ENABLED': 'false', 'DEER_FLOW_MODEL_METRICS_ENABLED': 'true'}
CHILD_B64 = ''
CHILD_SHA256 = '7a620bffcec4a21ce22caee85bdc7eca79809be08dce6b278999b11fc326509e'
KNOWN_NODES = {'ecs-zdz-pro-%04d' % n for n in range(18, 23)}


class Refused(Exception):
    pass


def require(ok, code):
    if not ok:
        raise Refused(code)


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':')).encode()


def bounded(argv, payload=None, timeout=25, cap=512 * 1024):
    p = subprocess.Popen(argv, stdin=subprocess.PIPE if payload else subprocess.DEVNULL,
                         stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    buffers = [bytearray(), bytearray()]
    overflow = threading.Event()
    def drain(stream, buf):
        while True:
            block = stream.read(8192)
            if not block:
                return
            if len(buf) + len(block) > cap:
                overflow.set()
                p.kill()
                return
            buf.extend(block)
    threads = [threading.Thread(target=drain, args=(s, b), daemon=True)
               for s, b in zip((p.stdout, p.stderr), buffers)]
    def feed():
        if payload:
            try:
                p.stdin.write(payload)
                p.stdin.close()
            except (BrokenPipeError, OSError):
                pass
    threads.append(threading.Thread(target=feed, daemon=True))
    for thread in threads:
        thread.start()
    try:
        p.wait(timeout=timeout)
    except subprocess.TimeoutExpired:
        p.kill()
        p.wait()
        raise Refused('READ_TIMEOUT')
    finally:
        for thread in threads:
            thread.join(2)
        for stream in (p.stdin, p.stdout, p.stderr):
            if stream is not None and not any(t.is_alive() for t in threads):
                stream.close()
    require(not overflow.is_set(), 'OUTPUT_BOUND')
    require(not any(t.is_alive() for t in threads), 'READ_THREAD_INCOMPLETE')
    require(p.returncode == 0, 'READ_COMMAND_FAILED')
    return bytes(buffers[0])


def dep_summary(obj, role):
    spec, state = obj['spec'], obj.get('status', {})
    containers = [c for c in spec['template']['spec']['containers'] if c['name'] == role]
    require(len(containers) == 1, 'CONTAINER_SHAPE')
    generation, desired, image = EXPECTED[role]
    require(obj['metadata']['generation'] == generation and containers[0]['image'] == image,
            'DEPLOYMENT_BASELINE_CHANGED_' + role)
    require(spec.get('replicas') == desired and not spec.get('paused'), 'DEPLOYMENT_PAUSED_OR_SCALED')
    require(state.get('observedGeneration') == generation and all(state.get(k) == desired for k in
            ('replicas', 'updatedReplicas', 'readyReplicas', 'availableReplicas')), 'ROLLOUT_NOT_CONVERGED')
    return {'uid': obj['metadata']['uid'], 'generation': generation, 'image': image,
            'spec_sha256': hashlib.sha256(canonical(spec)).hexdigest(), 'ready': desired}


def project_env(container):
    result = {}
    for name, expected in ENV.items():
        records = [x for x in container.get('env', []) if x.get('name') == name]
        result[name] = {'explicit_count': len(records),
                        'matches_expected': len(records) == 1 and records[0].get('value') == expected,
                        'value_from_reference': any('valueFrom' in x for x in records)}
    return result


def parse_index(raw):
    rows = [line.split() for line in raw.decode().splitlines() if line.strip()]
    require(all(len(row) == 8 for row in rows), 'POD_INDEX_SHAPE')
    require(len({row[0] for row in rows}) == len(rows), 'DUPLICATE_POD')
    require(all(re.fullmatch(r'[a-z0-9][a-z0-9.-]*', row[0]) for row in rows), 'POD_NAME')
    return sorted(rows)


def main():
    report = {'schema': 'portal-enterprise-production-comparison.v1', 'git_ref': REF,
              'status': 'INCOMPLETE', 'read_only': True, 'files_modified': False,
              'workload_modified': False, 'configuration_modified': False,
              'database_access': False, 'provider_requests': 0, 'callback_requests': 0,
              'secret_api_reads': 0, 'automatic_retry': False, 'samples': [],
              'scope': 'all_pod_image_metadata_and_one_gateway_source_sample_per_node',
              'all_gateway_processes_verified': False, 'python_sources_only': True,
              'dependencies_verified': False, 'browser_business_acceptance_claimed': False}
    deadline = time.monotonic() + 240
    try:
        require(sys.platform == 'linux' and os.uname().nodename.split('.')[0] == 'datax-01', 'WRONG_HOST')
        require(os.geteuid() == 0, 'ROOT_REQUIRED')
        kubectl = shutil.which('kubectl')
        require(kubectl is not None, 'KUBECTL_NOT_FOUND')
        base = [kubectl, '--kubeconfig=/etc/kubernetes/admin.conf', '--request-timeout=15s', '-n', 'deer-flow']
        child = zlib.decompress(base64.b64decode(CHILD_B64))
        require(hashlib.sha256(child).hexdigest() == CHILD_SHA256, 'CHILD_SEAL_CHANGED')
        def read(args, payload=None):
            report['last_step'] = ':'.join(args[:3])
            remaining = deadline - time.monotonic()
            require(remaining > 0, 'TOTAL_DEADLINE')
            return bounded(base + args, payload, min(30, remaining))
        def get(kind, name):
            return json.loads(read(['get', kind, name, '-o', 'json']))
        before = {role: get('deployment', role) for role in EXPECTED}
        report['deployments'] = {role: dep_summary(obj, role) for role, obj in before.items()}
        gwcontainer = next(c for c in before['gateway']['spec']['template']['spec']['containers'] if c['name'] == 'gateway')
        report['deployment_configuration'] = project_env(gwcontainer)
        columns = 'custom-columns=NAME:.metadata.name,UID:.metadata.uid,NODE:.spec.nodeName,PHASE:.status.phase,DELETING:.metadata.deletionTimestamp,READY:.status.containerStatuses[*].ready,IMAGE:.spec.containers[*].image,IMAGEID:.status.containerStatuses[*].imageID'
        def index(role):
            rows = parse_index(read(['get', 'pods', '-l', 'app=' + role, '-o', columns, '--no-headers']))
            generation, count, image = EXPECTED[role]
            require(len(rows) == count, 'POD_COUNT_CHANGED_' + role)
            digest = image.split('@')[1]
            require(all(r[3:6] == ['Running', '<none>', 'true'] and r[6] == image and r[7].endswith(digest) for r in rows), 'POD_IMAGE_OR_READY_CHANGED_' + role)
            return rows
        indexes = {role: index(role) for role in EXPECTED}
        report['pod_image_metadata_verified'] = {role: len(rows) for role, rows in indexes.items()}
        require({row[2] for row in indexes['gateway']} == KNOWN_NODES, 'GATEWAY_NODE_COVERAGE_CHANGED')
        samples = {}
        for row in indexes['gateway']:
            samples.setdefault(row[2], row)
        for node, row in sorted(samples.items()):
            name, uid = row[:2]
            pod = get('pod', name)
            require(pod['metadata']['uid'] == uid and not pod['metadata'].get('deletionTimestamp'), 'SAMPLE_CHANGED')
            owners = [x for x in pod['metadata'].get('ownerReferences', []) if x.get('controller')]
            require(len(owners) == 1 and owners[0].get('kind') == 'ReplicaSet', 'POD_OWNER')
            rs = get('replicaset', owners[0]['name'])
            require(rs['metadata']['uid'] == owners[0]['uid'] and any(x.get('controller') and x.get('uid') == before['gateway']['metadata']['uid'] and x.get('kind') == 'Deployment' for x in rs['metadata'].get('ownerReferences', [])), 'REPLICASET_OWNER')
            container = next(c for c in pod['spec']['containers'] if c['name'] == 'gateway')
            print(json.dumps({'phase': 'READ_GATEWAY_SOURCE_AND_STARTUP_ENV', 'node': node, 'sample': len(report['samples']) + 1, 'total': 5}), flush=True)
            observation = json.loads(read(['exec', '-i', name, '-c', 'gateway', '--', 'python', '-I', '-B', '-'], child))
            report['samples'].append({'pod': name, 'uid': uid, 'node': node,
                                      'pod_configuration': project_env(container), 'observation': observation})
            after_pod = get('pod', name)
            require(after_pod['metadata']['uid'] == uid and after_pod.get('status', {}).get('containerStatuses') == pod.get('status', {}).get('containerStatuses'), 'SAMPLE_RESTARTED_DURING_READ')
        after = {role: dep_summary(get('deployment', role), role) for role in EXPECTED}
        require(after == report['deployments'], 'DEPLOYMENT_CHANGED_DURING_READ')
        require(all(index(role) == indexes[role] for role in EXPECTED), 'POD_SET_CHANGED_DURING_READ')
        report['stable_readback'] = True
        report['source_samples_match'] = all(x['observation']['source_comparison']['status'] == 'MATCH' for x in report['samples'])
        report['status'] = 'READONLY_COMPARISON_OBSERVED'
    except Exception as exc:
        report.update(error_class=type(exc).__name__, error_code=str(exc) if isinstance(exc, Refused) else 'LOCAL_INSPECTION_FAILED')
    print(json.dumps(report, sort_keys=True))
    return 0 if report['status'] == 'READONLY_COMPARISON_OBSERVED' else 1


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--inspect-readonly', action='store_true', required=True)
    parser.parse_args()
    raise SystemExit(main())
